import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    subarrays = []
    for _ in range(m):
        l = int(next(iterator))
        r = int(next(iterator))
        subarrays.append((l, r))

    max_happiness = 0

    for mask in range(1 << m):
        current_happiness = 0
        counts = [0] * n

        for i in range(m):
            if (mask >> i) & 1:
                l, r = subarrays[i]
                for idx in range(l - 1, r):
                    counts[idx] += 1

        for i in range(n):
            current_happiness += a[i] * counts[i]

        if current_happiness > max_happiness:
            max_happiness = current_happiness

    print(max_happiness)

if __name__ == "__main__":
    main()
